# ==============================================# infra_guard.py — pause entries when infra degrades# ==============================================import aiohttp, asyncio, timefrom datetime import datetime, timezoneimport osfrom utils_pkg.core_utils import send_telegramRPC_URL = os.getenv("RPC_URL")USDC_MINT = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"SOL_MINT = "So11111111111111111111111111111111111111112"JUP_API = os.getenv("JUPITER_SWAP_API", "https://quote-api.jup.ag/v6")REDIS_URL = os.getenv("REDIS_URL", "redis://localhost:6379")try:    import redis.asyncio as aioredisexcept Exception:    aioredis = NoneINFRA_LATENCY_MAX_MS = int(os.getenv("INFRA_LATENCY_MAX_MS", "1200"))INFRA_JUP_MAX_MS = int(os.getenv("INFRA_JUP_MAX_MS", "1500"))INFRA_ERROR_BURST = int(os.getenv("INFRA_ERROR_BURST", "5"))POLL_SEC = int(os.getenv("INFRA_POLL_SEC", "20"))KEY_HALTED = "infra:halt"async def _redis():    if aioredis is None:        return None    return aioredis.from_url(REDIS_URL, decode_responses=True)async def _rpc_latency(session):    payload = {"jsonrpc":"2.0","id":1,"method":"getHealth"}    t0 = time.time()    try:        async with session.post(RPC_URL, json=payload, timeout=10) as r:            await r.text()            return int((time.time()-t0)*1000), r.status == 200    except Exception:        return 10_000, Falseasync def _jup_latency(session):    params = {        "inputMint": SOL_MINT,        "outputMint": USDC_MINT,        "amount": 1000000,  # 0.001 SOL in lamports        "slippageBps": 50,    }    t0 = time.time()    try:        async with session.get(f"{JUP_API}/quote", params=params, timeout=10) as r:            await r.text()            return int((time.time()-t0)*1000), r.status == 200    except Exception:        return 10_000, Falseasync def run_infra_guard():    r = await _redis()    await send_telegram("??? Infra guard started.")    err_streak = 0    async with aiohttp.ClientSession() as session:        while True:            lat, ok1 = await _rpc_latency(session)            jlat, ok2 = await _jup_latency(session)            halted = (lat > INFRA_LATENCY_MAX_MS) or (jlat > INFRA_JUP_MAX_MS) or (not ok1) or (not ok2)            if halted:                err_streak += 1            else:                err_streak = 0            final_halt = halted and err_streak >= INFRA_ERROR_BURST            if r:                await r.set(KEY_HALTED, "1" if final_halt else "0", ex=POLL_SEC*2)            if final_halt:                await send_telegram(f"?? Infra halt: RPC {lat}ms / JUP {jlat}ms (streak={err_streak})")            await asyncio.sleep(POLL_SEC)if __name__ == "__main__":    asyncio.run(run_infra_guard())